import{_ as i}from"./chunks/ai-pipeline-09-90-day-roadmap.DrUcRZwu.js";import{_ as a,o as t,c as o,a0 as l}from"./chunks/framework.DScjKhBS.js";const m=JSON.parse('{"title":"30-60-90 day rollout","description":"Implementation plan, KPIs, and stop conditions for restoring review reliability.","frontmatter":{"title":"30-60-90 day rollout","description":"Implementation plan, KPIs, and stop conditions for restoring review reliability."},"headers":[],"relativePath":"reports/pr-review-continuity/06-30-60-90-rollout.md","filePath":"reports/pr-review-continuity/06-30-60-90-rollout.md"}'),r={name:"reports/pr-review-continuity/06-30-60-90-rollout.md"};function n(s,e,c,d,h,u){return t(),o("div",null,[...e[0]||(e[0]=[l('<figure class="report-section-image-wrapper" aria-labelledby="fig-pr-rollout-caption"><img src="'+i+'" alt="Three-stage roadmap path with milestones and checkpoints" loading="lazy" class="report-section-image"><figcaption id="fig-pr-rollout-caption">Rollout plan: staged 30-60-90 progression with measurable checkpoints</figcaption></figure><h1 id="_30-60-90-day-rollout" tabindex="-1">30-60-90 day rollout <a class="header-anchor" href="#_30-60-90-day-rollout" aria-label="Permalink to &quot;30-60-90 day rollout&quot;">​</a></h1><h2 id="day-0-30-stabilize" tabindex="-1">Day 0-30: Stabilize <a class="header-anchor" href="#day-0-30-stabilize" aria-label="Permalink to &quot;Day 0-30: Stabilize&quot;">​</a></h2><h3 id="objectives" tabindex="-1">Objectives <a class="header-anchor" href="#objectives" aria-label="Permalink to &quot;Objectives&quot;">​</a></h3><ul><li>Stop review quality degradation</li><li>Restore predictable queue flow</li><li>Prevent high-risk merges without sufficient evidence</li></ul><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ol><li>Introduce PR evidence contract (<code>Intent/Risk/Evidence/Rollback</code>)</li><li>Enforce PR sizing and decomposition guidance</li><li>Classify PRs by review tier (T1/T2/T3)</li><li>Add/validate deterministic CI gates (tests + security scans)</li><li>Enable first-pass AI review bot with no merge permissions</li></ol><h3 id="kpis" tabindex="-1">KPIs <a class="header-anchor" href="#kpis" aria-label="Permalink to &quot;KPIs&quot;">​</a></h3><ul><li>Time to first meaningful review</li><li>Median PR size</li><li>% PRs compliant with evidence contract</li></ul><hr><h2 id="day-31-60-harden" tabindex="-1">Day 31-60: Harden <a class="header-anchor" href="#day-31-60-harden" aria-label="Permalink to &quot;Day 31-60: Harden&quot;">​</a></h2><h3 id="objectives-1" tabindex="-1">Objectives <a class="header-anchor" href="#objectives-1" aria-label="Permalink to &quot;Objectives&quot;">​</a></h3><ul><li>Improve review depth consistency across reviewers</li><li>Reduce concentration risk</li></ul><h3 id="actions-1" tabindex="-1">Actions <a class="header-anchor" href="#actions-1" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ol><li>Introduce reviewer rotation for key subsystems</li><li>Add domain-owner sign-off for T3 PRs</li><li>Create checklist-driven review templates by risk class</li><li>Run weekly defect/revert retros on merged PRs</li></ol><h3 id="kpis-1" tabindex="-1">KPIs <a class="header-anchor" href="#kpis-1" aria-label="Permalink to &quot;KPIs&quot;">​</a></h3><ul><li>Review concentration ratio (top 1-2 reviewers)</li><li>T3 compliance rate (all required checks present)</li><li>Rework churn trend</li></ul><hr><h2 id="day-61-90-institutionalize" tabindex="-1">Day 61-90: Institutionalize <a class="header-anchor" href="#day-61-90-institutionalize" aria-label="Permalink to &quot;Day 61-90: Institutionalize&quot;">​</a></h2><h3 id="objectives-2" tabindex="-1">Objectives <a class="header-anchor" href="#objectives-2" aria-label="Permalink to &quot;Objectives&quot;">​</a></h3><ul><li>Make the model durable beyond the temporary capacity shock</li><li>Build knowledge redundancy</li></ul><h3 id="actions-2" tabindex="-1">Actions <a class="header-anchor" href="#actions-2" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ol><li>Codify policies in <code>CONTRIBUTING</code> and team playbooks</li><li>Expand subsystem ownership and backup reviewer coverage</li><li>Publish monthly review health dashboard</li><li>Tune thresholds based on actual defect and latency outcomes</li></ol><h3 id="kpis-2" tabindex="-1">KPIs <a class="header-anchor" href="#kpis-2" aria-label="Permalink to &quot;KPIs&quot;">​</a></h3><ul><li>Post-merge regression rate vs baseline</li><li>Queue SLA attainment rate</li><li>Percentage of repos using standardized review model</li></ul><hr><h2 id="stop-conditions-and-rollback" tabindex="-1">Stop conditions and rollback <a class="header-anchor" href="#stop-conditions-and-rollback" aria-label="Permalink to &quot;Stop conditions and rollback&quot;">​</a></h2><p>Temporarily tighten merge policy (or pause non-critical changes) if:</p><ul><li>Regression rate exceeds agreed threshold vs baseline</li><li>T3 PRs bypass mandatory evidence or sign-off</li><li>Queue health collapses beyond agreed latency window</li></ul><p>Re-enable normal flow after two consecutive stable reporting periods.</p><hr><p><strong>Next:</strong> <a href="./reports/pr-review-continuity/07-sources-and-evidence-map.html">Sources and evidence map</a></p>',32)])])}const f=a(r,[["render",n]]);export{m as __pageData,f as default};
